// Validate a new tax document before it enters the file queue.
// Rules: mock/policies/06-israeli-tax-invoice-rules.md
const VAT_SWITCH = Date.parse('2025-01-01T00:00:00Z'); // 17% before, 18% from
const round2 = (n) => Math.round(n * 100) / 100;

// Which of the three triggers fired? Only one has items in a given run.
let docType = 'Invoice';
for (const [node, type] of [['New Invoice', 'Invoice'], ['New TaxInvoice', 'TaxInvoice'], ['New Receipt', 'Receipt']]) {
  try { if ($(node).all().length) { docType = type; break; } } catch (e) { /* node did not run */ }
}

const out = [];
for (const item of $input.all()) {
  const f = item.json.fields || item.json;
  const recordId = item.json.id || f.id || '';
  const errors = [];

  const docNumber = Number(f.DocNumber);
  if (!Number.isInteger(docNumber) || docNumber <= 0) errors.push('DocNumber must be a positive integer');
  if (!f.CustomerId) errors.push('CustomerId is missing');

  const issue = f.IssueDate ? Date.parse(f.IssueDate) : NaN;
  if (Number.isNaN(issue)) errors.push('IssueDate is missing or unparsable');

  if (docType === 'Receipt') {
    if (!(Number(f.Amount) > 0)) errors.push('Amount must be greater than 0');
    if (!f.PaymentMethod) errors.push('PaymentMethod is missing');
  } else {
    const subtotal = Number(f.Subtotal);
    const vatRate = Number(f.VATRate);
    const vatAmount = Number(f.VATAmount);
    const total = Number(f.Total);
    const expectedRate = !Number.isNaN(issue) && issue >= VAT_SWITCH ? 0.18 : 0.17;

    if (!(subtotal > 0)) errors.push('Subtotal must be greater than 0');
    if (vatRate !== expectedRate) errors.push(`VATRate ${vatRate} should be ${expectedRate} for ${f.IssueDate}`);
    if (Math.abs(round2(subtotal * vatRate) - round2(vatAmount)) > 0.02) errors.push('VATAmount does not match Subtotal x VATRate');
    if (Math.abs(round2(subtotal + vatAmount) - round2(total)) > 0.02) errors.push('Total does not match Subtotal + VATAmount');
    if (docType === 'TaxInvoice' && !f.CustomerBusinessNumber) errors.push('A tax invoice needs the customer business number');
  }

  const d = Number.isNaN(issue) ? new Date() : new Date(issue);
  out.push({ json: {
    docType,
    recordId,
    docNumber: f.DocNumber ?? null,
    valid: errors.length === 0,
    error: errors.join('; '),
    year: String(d.getUTCFullYear()),
    month: String(d.getUTCMonth() + 1).padStart(2, '0')
  }});
}
return out;
